xpath.script:
(function () {
  /* Easing for arrow/wheel animations (not used during drag) */
  const EASE = (t)=> t < 0.5 ? 4*t*t*t : 1 - Math.pow(-2*t+2, 3)/2;

  function smoothScrollTo(el, target, duration = 360) {
    const start = el.scrollLeft, dist = target - start;
    if (!dist || duration <= 0) { el.scrollLeft = target; return; }
    let t0;
    const step = (ts) => {
      if (!t0) t0 = ts;
      const p = Math.min(1, (ts - t0) / duration);
      el.scrollLeft = start + dist * EASE(p);
      if (p < 1) requestAnimationFrame(step);
    };
    requestAnimationFrame(step);
  }

  /* Mobile-like momentum after releasing drag */
  function kineticScroll(el, vScroll /* px/ms */) {
    const max = Math.max(0, el.scrollWidth - el.clientWidth);
    let prev = performance.now();
    let v = vScroll;               // current velocity (px/ms), sign matters
    const minV = 0.02;             // stop threshold
    const friction = 0.95;         // per 16ms frame decay (~mobile feel)

    function step(ts) {
      const dt = ts - prev;        // ms
      prev = ts;
      const decay = Math.pow(friction, dt / 16);
      v *= decay;
      if (Math.abs(v) < minV) return;

      let next = el.scrollLeft + v * dt;
      if (next < 0) { next = 0; v = 0; }
      if (next > max) { next = max; v = 0; }

      el.scrollLeft = next;
      if (v !== 0) requestAnimationFrame(step);
    }
    requestAnimationFrame(step);
  }

  function initWrap(wrap) {
    const slider   = wrap.querySelector('.subcategory-slider');
    const leftBtn  = wrap.querySelector('.slider-arrow-left');
    const rightBtn = wrap.querySelector('.slider-arrow-right');

    // Show each arrow only when you can scroll that way
    const updateArrows = () => {
      const max = Math.max(0, slider.scrollWidth - slider.clientWidth);
      const atStart = slider.scrollLeft <= 1;
      const atEnd   = slider.scrollLeft >= (max - 1);
      const hasOverflow = slider.scrollWidth > slider.clientWidth + 4;

      leftBtn.hidden  = !hasOverflow || atStart;
      rightBtn.hidden = !hasOverflow || atEnd;

      leftBtn.disabled  = atStart;
      rightBtn.disabled = atEnd;

      wrap.classList.toggle('at-start', atStart);
      wrap.classList.toggle('at-end', atEnd);
    };

    // Arrow clicks -> eased scroll by a page
    const PAGE = () => Math.max(240, Math.floor(slider.clientWidth * 0.8));
    leftBtn.addEventListener('click', () => {
      smoothScrollTo(slider, Math.max(0, slider.scrollLeft - PAGE()), 360);
    });
    rightBtn.addEventListener('click', () => {
      const max = slider.scrollWidth - slider.clientWidth;
      smoothScrollTo(slider, Math.min(max, slider.scrollLeft + PAGE()), 360);
    });

    // Drag with mobile-like inertia
    let isDown = false, startX = 0, startScroll = 0, moved = false;
    let lastX = 0, lastT = 0, vx = 0; // finger velocity in px/ms

    const start = (clientX) => {
      isDown = true; moved = false; vx = 0;
      slider.classList.add('is-dragging');
      startX = clientX - slider.getBoundingClientRect().left;
      startScroll = slider.scrollLeft;
      lastX = clientX; lastT = performance.now();
    };
    const move = (clientX) => {
      if (!isDown) return;
      const x = clientX - slider.getBoundingClientRect().left;
      const walk = x - startX;
      if (Math.abs(walk) > 3) moved = true;

      const now = performance.now(), dt = now - lastT || 1;
      vx = (clientX - lastX) / dt;   // finger velocity (px/ms)
      lastX = clientX; lastT = now;

      // Content follows finger
      slider.scrollLeft = startScroll - walk;
      updateArrows();
    };
    const end = () => {
      if (!isDown) return;
      isDown = false;
      slider.classList.remove('is-dragging');

      // Convert finger velocity -> scroll velocity
      // When finger moves right (vx>0), scrollLeft decreased while dragging.
      // So scroll velocity is the opposite sign:
      const vScroll = -vx;           // px/ms
      kineticScroll(slider, vScroll);
    };

    // Mouse
    slider.addEventListener('mousedown', e => {
      if (e.button !== 0) return;
      start(e.clientX); e.preventDefault();
    });
    window.addEventListener('mousemove', e => move(e.clientX));
    window.addEventListener('mouseup', end);
    slider.addEventListener('mouseleave', end);

    // Touch
    slider.addEventListener('touchstart', e => {
      const t = e.touches[0]; if (!t) return; start(t.clientX);
    }, { passive: true });
    slider.addEventListener('touchmove', e => {
      const t = e.touches[0]; if (!t) return; move(t.clientX);
    }, { passive: true });
    slider.addEventListener('touchend', end);

    // Cancel accidental clicks after drag
    slider.addEventListener('click', e => { if (moved) { e.preventDefault(); e.stopPropagation(); } }, true);



    slider.addEventListener('scroll', updateArrows, { passive: true });
    new ResizeObserver(updateArrows).observe(slider);
    updateArrows();
  }

  document.querySelectorAll('.subcategory-wrap').forEach(initWrap);
})();
